SELECT 'gongkao', '倍数概述', 'kp-xc-data-multiple-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"倍数概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"倍数约 3 题。核心公式：倍数 = A/B。注意「是几倍」和「多几倍」的区别 — 是几倍 = A/B，多几倍 = A/B - 1。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","content":[{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"子类"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期倍数：当前时期 A 是 B 的几倍"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期倍数：过去时期 A 是 B 的几倍"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"间隔倍数：跨两期的倍数关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"倍数比较：比较多个倍数的大小"}]}]}]}]},{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A/B"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A/B × (1+rB)/(1+rA)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"间隔公式"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"大小比较"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期倍数 = A / B"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期倍数 = (A/B) × (1+rB)/(1+rA)，其中 rA=A的增长率，rB=B的增长率"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"多几倍 = 倍数 - 1 = A/B - 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"倍数比较：直接比较 A/B 的大小"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「是几倍」vs「多几倍」— 是几倍 = A/B，多几倍 = A/B - 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期倍数公式中增长率的位置 — rB 在分子，rA 在分母"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"倍数比较时注意分子分母的对应关系"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"倍数公式简单，关键是区分「是几倍」和「多几倍」。建议做 10 题巩固。"}]}]}]}]}$$ AS jsonb), NULL, '倍数概述：现期倍数、基期倍数、间隔倍数、倍数比较。', category_node.id, CAST('["资料分析", "倍数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_multiple", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
